const WINDOWS = new Map()

function createLimiter(opts) {
  const kind = opts.kind
  let start = null
  let count = 0
  let log = []
  let tokens = opts.capacity || 0
  let level = 0
  let last = 0

  return {
    allow(now) {
      if (kind === 'fixed') {
        const win = Math.floor(now / opts.windowMs) * opts.windowMs
        if (win !== start) { start = win; count = 0 }
        if (count >= opts.limit) return false
        count++
        return true
      }
      if (kind === 'sliding-log') {
        log = log.filter((t) => now - t < opts.windowMs)
        if (log.length >= opts.limit) return false
        log.push(now)
        return true
      }
      if (kind === 'token') {
        const elapsed = now - last
        tokens = Math.min(opts.capacity, tokens + (elapsed / 1000) * opts.rate)
        last = now
        if (tokens < 1) return false
        tokens -= 1
        return true
      }
      const elapsed = now - last
      level = Math.max(0, level - (elapsed / 1000) * opts.rate)
      last = now
      if (level >= opts.capacity) return false
      level += 1
      return true
    }
  }
}

stages.test:
{
  check('固定窗口：窗口内限额用满后拒绝', () => {
    const l = createLimiter({ kind: 'fixed', limit: 3, windowMs: 1000 })
    same([l.allow(0), l.allow(100), l.allow(200)], [true, true, true])
    same(l.allow(300), false, '第 4 个请求必须被拒')
  })
  check('固定窗口：跨窗口后重新计数', () => {
    const l = createLimiter({ kind: 'fixed', limit: 2, windowMs: 1000 })
    l.allow(0); l.allow(10)
    same(l.allow(900), false)
    same(l.allow(1000), true, '1000 属于下一个窗口')
  })
  check('滑动日志：窗口滑走后放行（固定窗口做不到）', () => {
    const l = createLimiter({ kind: 'sliding-log', limit: 2, windowMs: 1000 })
    same(l.allow(0), true)
    same(l.allow(500), true)
    same(l.allow(999), false, '0ms 那条还在窗口内')
    same(l.allow(1001), true, '0ms 已滑出窗口')
  })
  check('令牌桶：初始容量 + 按速率补令牌', () => {
    const l = createLimiter({ kind: 'token', capacity: 5, rate: 10 })
    const burst = []
    for (let i = 0; i < 6; i++) burst.push(l.allow(0))
    same(burst, [true, true, true, true, true, false], '容量 5，第 6 个没令牌')
    same(l.allow(100), true, '100ms 补 1 个令牌')
    same(l.allow(150), false, '再过 50ms 只攒下 0.5 个')
  })
  check('漏桶：水位封顶，按速率匀速漏出', () => {
    const l = createLimiter({ kind: 'leaky', capacity: 3, rate: 10 })
    same([l.allow(0), l.allow(0), l.allow(0)], [true, true, true])
    same(l.allow(0), false, '水位到顶')
    same(l.allow(100), true, '100ms 漏掉 1 个单位')
  })
}

