const WINDOWS = new Map()

function createLimiter(opts) {
  const kind = opts.kind
  let start = null
  let count = 0
  let log = []
  let tokens = opts.capacity || 0
  let level = 0
  let last = 0

  return {
    allow(now) {
      if (kind === 'fixed') {
        const win = Math.floor(now / opts.windowMs) * opts.windowMs
        if (win !== start) { start = win; count = 0 }
        if (count >= opts.limit) return false
        count++
        return true
      }
      if (kind === 'sliding-log') {
        log = log.filter((t) => now - t < opts.windowMs)
        if (log.length >= opts.limit) return false
        log.push(now)
        return true
      }
      if (kind === 'token') {
        const elapsed = now - last
        tokens = Math.min(opts.capacity, tokens + (elapsed / 1000) * opts.rate)
        last = now
        if (tokens < 1) return false
        tokens -= 1
        return true
      }
      const elapsed = now - last
      level = Math.max(0, level - (elapsed / 1000) * opts.rate)
      last = now
      if (level >= opts.capacity) return false
      level += 1
      return true
    }
  }
}

function createBreaker(opts) {
  const failureThreshold = opts.failureThreshold
  const successThreshold = opts.successThreshold
  const openMs = opts.openMs

  let state = 'closed'
  let failures = 0
  let successes = 0
  let openUntil = 0

  function tick(now) {
    if (state === 'open' && now >= openUntil) {
      state = 'half-open'
      successes = 0
    }
  }

  return {
    call(ok, now) {
      tick(now)
      if (state === 'open') return { allowed: false, state: 'open' }
      if (ok) {
        failures = 0
        if (state === 'half-open') {
          successes++
          if (successes >= successThreshold) { state = 'closed'; successes = 0 }
        }
        return { allowed: true, state }
      }
      failures++
      if (state === 'half-open' || failures >= failureThreshold) {
        state = 'open'
        openUntil = now + openMs
        failures = 0
        successes = 0
      }
      return { allowed: true, state }
    },
    state(now) {
      tick(now)
      return state
    }
  }
}

stages.test:
{
  check('连续失败达到阈值 → 打开并短路', () => {
    const b = createBreaker({ failureThreshold: 3, successThreshold: 2, openMs: 1000 })
    same([b.call(false, 0).allowed, b.call(false, 10).allowed], [true, true])
    const r = b.call(false, 20)
    same(r.allowed, true, '触发那次本身还是放行的')
    same(r.state, 'open')
    same(b.call(true, 30).allowed, false, '打开期间一律不进下游')
  })
  check('一次成功就把失败计数清零', () => {
    const b = createBreaker({ failureThreshold: 3, successThreshold: 1, openMs: 1000 })
    b.call(false, 0); b.call(true, 10); b.call(false, 20); b.call(false, 30)
    same(b.state(30), 'closed', '中间那次成功打断了连续失败')
  })
  check('冷却到期进入半开，放行探测', () => {
    const b = createBreaker({ failureThreshold: 2, successThreshold: 1, openMs: 1000 })
    b.call(false, 0); b.call(false, 1)
    same(b.call(true, 500).allowed, false, '还没到期')
    const probe = b.call(true, 1002)
    same(probe.allowed, true)
    same(probe.state, 'closed', '够 successThreshold 就恢复')
  })
  check('半开时探测失败 → 立刻回到打开并重新计时', () => {
    const b = createBreaker({ failureThreshold: 1, successThreshold: 1, openMs: 1000 })
    b.call(false, 0)
    b.call(false, 1001)
    same(b.state(1500), 'open')
    same(b.call(true, 1999).allowed, false)
    same(b.call(true, 2002).state, 'closed')
  })
  check('半开要攒够 successThreshold 次成功才关闭', () => {
    const b = createBreaker({ failureThreshold: 1, successThreshold: 2, openMs: 1000 })
    b.call(false, 0)
    same(b.call(true, 1001).allowed, true)
    same(b.state(1001), 'half-open', '只成功 1 次还不够')
    same(b.call(true, 1002).state, 'closed')
  })
}

