function createBreaker(opts) {
  const failureThreshold = opts.failureThreshold
  const successThreshold = opts.successThreshold
  const openMs = opts.openMs

  let state = 'closed'
  let failures = 0
  let successes = 0
  let openUntil = 0

  function tick(now) {
    if (state === 'open' && now >= openUntil) {
      state = 'half-open'
      successes = 0
    }
  }

  return {
    call(ok, now) {
      tick(now)
      if (state === 'open') return { allowed: false, state: 'open' }
      if (ok) {
        failures = 0
        if (state === 'half-open') {
          successes++
          if (successes >= successThreshold) { state = 'closed'; successes = 0 }
        }
