function mergeFeeds(lists, limit) {
  if (!limit || limit <= 0) return []
  const seen = new Set()
  const all = []
  lists.forEach((list, source) => {
    for (const item of list) {
      if (seen.has(item.id)) continue
      seen.add(item.id)
      all.push({ id: item.id, t: item.t, source })
    }
  })
  all.sort((a, b) => b.t - a.t)
  return all.slice(0, limit)
}

function createSeckill(opts) {
  let left = opts.stock
  const buyers = new Map()
  let seq = 0

  return {
    grab(userId, now) {
      const prev = buyers.get(userId)
      if (prev) {
        if (!opts.perUser) return { code: 'OK', seq: prev.seq, stock: left }
        if (prev.count >= opts.perUser) {
          return { code: 'LIMIT', seq: prev.seq, stock: left }
        }
        prev.count++
        left--
        return { code: 'OK', seq: prev.seq, stock: left }
      }
      if (left <= 0) return { code: 'SOLD_OUT', seq: -1, stock: left }
      seq++
      buyers.set(userId, { count: 1, seq })
      left--
      return { code: 'OK', seq, stock: left }
    },
    stock() { return left }
  }
}

stages.test:
{
  check('多路时间线合并：按时间倒序取前 N', () => {
    const a = [{ id: 'p1', t: 100 }, { id: 'p2', t: 50 }]
    const b = [{ id: 'p3', t: 90 }, { id: 'p4', t: 10 }]
    const out = mergeFeeds([a, b], 3)
    same(out.map((x) => x.id), ['p1', 'p3', 'p2'])
    same(out.map((x) => x.source), [0, 1, 0])
  })
  check('同一条内容在多个时间线里只出现一次', () => {
    const out = mergeFeeds([[{ id: 'x', t: 5 }], [{ id: 'x', t: 5 }, { id: 'y', t: 4 }]], 10)
    same(out.map((x) => x.id), ['x', 'y'])
  })
  check('空列表与 limit=0 的边界', () => {
    same(mergeFeeds([[], []], 5), [])
    same(mergeFeeds([[{ id: 'a', t: 1 }]], 0), [])
  })
  check('秒杀：卖完为止，绝不超卖', () => {
    const s = createSeckill({ stock: 2 })
    same(s.grab('u1', 0).code, 'OK')
    same(s.grab('u2', 0).code, 'OK')
    same(s.grab('u3', 0).code, 'SOLD_OUT')
    same(s.stock(), 0)
  })
  check('秒杀：同一用户重复请求幂等', () => {
    const s = createSeckill({ stock: 5 })
    const r1 = s.grab('u1', 0)
    const r2 = s.grab('u1', 100)
    same(r2.code, 'OK')
    same(r2.seq, r1.seq, '返回首次结果，不重复扣减')
    same(s.stock(), 4)
  })
  check('秒杀：每人限购', () => {
    const s = createSeckill({ stock: 10, perUser: 2 })
    s.grab('u1', 0); s.grab('u1', 0)
    same(s.grab('u1', 0).code, 'LIMIT')
  })
}

