stages.code:
function parseDockerfile(text) {
  const stages = []
  let current = null

  for (const raw of String(text || '').split('\n')) {
    const line = raw.trim()
    if (!line || line.startsWith('#')) continue
    const parts = line.split(/\s+/)
    const cmd = parts[0].toUpperCase()
    const args = parts.slice(1)

    if (cmd === 'FROM') {
      const asIdx = args.findIndex((a) => a.toUpperCase() === 'AS')
      const base = args[0]
      const name = asIdx >= 0 ? args[asIdx + 1] : null
      current = { index: stages.length, name, base, instructions: [], expose: [] }
      stages.push(current)
      continue
    }
    if (!current) continue

    const ins = { cmd, args }
    if (cmd === 'COPY' || cmd === 'ADD') {
      const fromIdx = args.findIndex((a) => a.startsWith('--from='))
      if (fromIdx >= 0) {
        ins.copyFrom = args[fromIdx].slice('--from='.length)
        ins.args = args.filter((a) => !a.startsWith('--from='))
        ins.args = ins.args.filter((a) => !a.startsWith('--'))
      }
    }
    if (cmd === 'EXPOSE') {
      for (const a of args) current.expose.push(Number(a))
    }
    current.instructions.push(ins)
  }

  return { stages, finalStage: stages.length ? stages.length - 1 : -1 }
}

