{
  var DF = [
    'FROM node:20-alpine AS build',
    'WORKDIR /app',
    'COPY package.json pnpm-lock.yaml ./',
    'RUN pnpm install',
    'COPY . .',
    'RUN pnpm build',
    '',
    'FROM nginx:1.27-alpine AS runtime',
    'COPY --from=build /app/dist /usr/share/nginx/html',
    'EXPOSE 80 443',
    'CMD ["nginx", "-g", "daemon off;"]'
  ].join('\n')

  check('多阶段：阶段名与基础镜像', () => {
    const d = parseDockerfile(DF)
    same(d.stages.length, 2)
    same(d.stages.map((s) => s.name), ['build', 'runtime'])
    same(d.stages.map((s) => s.base), ['node:20-alpine', 'nginx:1.27-alpine'])
  })
  check('最终阶段是最后一个 FROM', () => {
    const d = parseDockerfile(DF)
    same(d.finalStage, 1)
    same(d.stages[1].instructions.map((i) => i.cmd), ['COPY', 'EXPOSE', 'CMD'])
  })
  check('EXPOSE 收集端口', () => {
    const d = parseDockerfile(DF)
    same(d.stages[1].expose, [80, 443])
    same(d.stages[0].expose, [])
  })
  check('COPY --from 记录来源阶段', () => {
    const d = parseDockerfile(DF)
