function schedule(pod, nodes) {
  const feasible = []
  const rejected = []
  const req = pod.requests || {}
  const selector = pod.selector || {}
  const tolerations = pod.tolerations || []

  for (const node of nodes) {
    if (node.unschedulable) {
      rejected.push({ node: node.name, reason: 'unschedulable' })
      continue
    }
    let matched = true
    for (const key of Object.keys(selector)) {
      if ((node.labels || {})[key] !== selector[key]) { matched = false; break }
    }
    if (!matched) {
      rejected.push({ node: node.name, reason: 'selector-mismatch' })
      continue
    }
    const untolerated = (node.taints || []).find((t) => !tolerations.includes(t))
    if (untolerated) {
      rejected.push({ node: node.name, reason: 'taint' })
      continue
    }
    if ((req.cpu || 0) > node.cpu) {
      rejected.push({ node: node.name, reason: 'insufficient-cpu' })
      continue
    }
    if ((req.mem || 0) > node.mem) {
      rejected.push({ node: node.name, reason: 'insufficient-mem' })
      continue
    }
    feasible.push(node.name)
  }
  return { feasible, rejected }
}

