      continue
    }
    if ((req.cpu || 0) > node.cpu) {
      rejected.push({ node: node.name, reason: 'insufficient-cpu' })
      continue
    }
    if ((req.mem || 0) > node.mem) {
      rejected.push({ node: node.name, reason: 'insufficient-mem' })
      continue
    }
    feasible.push(node.name)
  }
  return { feasible, rejected }
