function probeAction(probes) {
  const startup = probes.startup
  const liveness = probes.liveness || { pass: true }
  const readiness = probes.readiness || { pass: true }

  if (startup && !startup.pass) {
    if (startup.threshold && (startup.attempts || 0) >= startup.threshold) return 'restart'
    return 'wait-startup'
  }
  if (!liveness.pass) return 'restart'
  if (!readiness.pass) return 'not-ready'
  return 'ready'
