function rolloutPlan(opts) {
  const replicas = opts.replicas
  const surge = resolveCount(opts.maxSurge, replicas)
  const unavailable = resolveCount(opts.maxUnavailable, replicas)

  if (surge === 0 && unavailable === 0) return { deadlock: true, steps: [], surge, unavailable }

  const step = surge || unavailable
  const steps = []
  let newN = 0
  let oldN = replicas

  while (newN < replicas) {
    newN = Math.min(replicas, newN + step)
    oldN = newN === replicas ? 0 : Math.min(oldN, replicas - newN + surge)
