function planPipeline(jobs) {
  const ids = new Set(jobs.map((j) => j.id))
  const missing = []
  for (const j of jobs) {
    for (const dep of j.needs || []) {
      if (!ids.has(dep)) missing.push(dep)
    }
  }

  const waves = []
  const done = new Set()
  const remaining = jobs.slice()

  while (remaining.length) {
    const ready = remaining.filter((j) => (j.needs || []).every((d) => done.has(d)))
    if (!ready.length) return { waves: [], cycle: true, missing }
    waves.push(ready.map((j) => j.id))
    for (const j of ready) {
      done.add(j.id)
      remaining.splice(remaining.indexOf(j), 1)
    }
  }
  return { waves, cycle: false, missing }
}

