function gitFlowTrigger(ctx) {
  if (ctx.tag) return ['release']
  const branch = ctx.branch || ''
  if (ctx.event === 'pull_request') return ['lint', 'test', 'build']
  if (branch === 'main' || branch === 'master') return ['build', 'deploy-staging', 'deploy-prod']
  if (branch.indexOf('hotfix/') === 0) return ['test', 'build', 'deploy-staging']
  if (branch.indexOf('release/') === 0) return ['build', 'deploy-staging']
  return ['lint', 'test']
}

