function planPipeline(jobs) {
  const ids = new Set(jobs.map((j) => j.id))
  const missing = []
  for (const j of jobs) {
    for (const dep of j.needs || []) {
      if (!ids.has(dep)) missing.push(dep)
    }
  }

  const waves = []
  const done = new Set()
  const remaining = jobs.slice()

  while (remaining.length) {
    const ready = remaining.filter((j) => (j.needs || []).every((d) => done.has(d)))
    if (!ready.length) return { waves: [], cycle: true, missing }
    waves.push(ready.map((j) => j.id))
    for (const j of ready) {
      done.add(j.id)
      remaining.splice(remaining.indexOf(j), 1)
    }
  }
  return { waves, cycle: false, missing }
}

function parseSemver(v) {
  const [core, pre] = String(v).split('-')
  return { nums: core.split('.').map(Number), pre: pre || null }
}

function compareVersion(a, b) {
  const x = parseSemver(a)
  const y = parseSemver(b)
  for (let i = 0; i < 3; i++) {
    const d = (x.nums[i] || 0) - (y.nums[i] || 0)
    if (d !== 0) return d > 0 ? 1 : -1
  }
  if (x.pre === y.pre) return 0
  if (!x.pre) return 1
  if (!y.pre) return -1
  return x.pre > y.pre ? 1 : -1
}

function bumpVersion(v, kind) {
  const { nums } = parseSemver(v)
  const [major, minor, patch] = nums
  if (kind === 'major') return major + 1 + '.0.0'
  if (kind === 'minor') return major + '.' + (minor + 1) + '.0'
  return major + '.' + minor + '.' + (patch + 1)
}

function artifactName(version, sha) {
  return 'app-' + version + '-' + String(sha).slice(0, 7)
}

function prune(versions, keep) {
  return versions.slice().sort(compareVersion).slice(versions.length - keep > 0 ? versions.length - keep : 0)
}

function gitFlowTrigger(ctx) {
  if (ctx.tag) return ['release']
  const branch = ctx.branch || ''
  if (ctx.event === 'pull_request') return ['lint', 'test', 'build']
  if (branch === 'main' || branch === 'master') return ['build', 'deploy-staging', 'deploy-prod']
  if (branch.indexOf('hotfix/') === 0) return ['test', 'build', 'deploy-staging']
  if (branch.indexOf('release/') === 0) return ['build', 'deploy-staging']
  return ['lint', 'test']
}

