levels.tests:
{
  check('无依赖的 job 全部并行（一个波次）', () => {
    const p = planPipeline([{ id: 'lint' }, { id: 'test' }, { id: 'build' }])
    same(p.cycle, false)
    same(p.waves.length, 1)
    same(p.waves[0], ['lint', 'test', 'build'])
  })
  check('链式依赖分成三波', () => {
    const p = planPipeline([
      { id: 'build', needs: ['test'] },
      { id: 'test', needs: ['lint'] },
      { id: 'lint' }
    ])
    same(p.waves.map((w) => w[0]), ['lint', 'test', 'build'])
  })
  check('菱形依赖：join 在最后一波', () => {
    const p = planPipeline([
      { id: 'a' },
      { id: 'b', needs: ['a'] },
      { id: 'c', needs: ['a'] },
      { id: 'd', needs: ['b', 'c'] }
    ])
    same(p.waves.length, 3)
    same(p.waves[0], ['a'])
    same(p.waves[1], ['b', 'c'])
    same(p.waves[2], ['d'])
  })
  check('有环就报 cycle，不返回半成品波次', () => {
    const p = planPipeline([{ id: 'a', needs: ['b'] }, { id: 'b', needs: ['a'] }])
    same(p.cycle, true)
    same(p.waves, [])
  })
  check('未知依赖单独报告 missing', () => {
    const p = planPipeline([{ id: 'build', needs: ['ghost'] }])
    same(p.missing, ['ghost'])
  })
}
{
  check('semver 递增', () => {
    same(bumpVersion('1.2.3', 'patch'), '1.2.4')
    same(bumpVersion('1.2.3', 'minor'), '1.3.0')
    same(bumpVersion('1.2.3', 'major'), '2.0.0')
  })
  check('制品名 = 应用-版本-短 sha', () => {
    same(artifactName('1.2.4', 'abcdef1234deadbeef'), 'app-1.2.4-abcdef1')
  })
  check('保留策略只留最近 N 个发布版', () => {
    same(prune(['1.0.0', '1.2.0', '1.1.0', '2.0.0'], 2), ['1.2.0', '2.0.0'])
  })
  check('版本比较按数值不是字典序', () => {
    same(compareVersion('1.9.0', '1.10.0'), -1)
    same(prune(['1.9.0', '1.10.0'], 1), ['1.10.0'])
  })
  check('预发布版本排在同版本正式版之前', () => {
    same(compareVersion('1.0.0-alpha', '1.0.0'), -1)
    same(compareVersion('1.0.0-rc.1', '1.0.0-rc.2'), -1)
    same(prune(['1.0.0', '1.0.0-rc.1'], 1), ['1.0.0'])
  })
}
{
  check('main 分支 push → 构建 + 两级部署', () => {
    same(gitFlowTrigger({ event: 'push', branch: 'main' }), ['build', 'deploy-staging', 'deploy-prod'])
  })
  check('PR → 只做检查与构建', () => {
    same(gitFlowTrigger({ event: 'pull_request', branch: 'main' }), ['lint', 'test', 'build'])
  })
  check('feature 分支 push 只跑检查', () => {
    same(gitFlowTrigger({ event: 'push', branch: 'feature/login' }), ['lint', 'test'])
  })
  check('打 tag → 只出 release 制品', () => {
    same(gitFlowTrigger({ event: 'push', tag: 'v1.2.3' }), ['release'])
  })
  check('hotfix → 测试构建并只进 staging', () => {
    same(gitFlowTrigger({ event: 'push', branch: 'hotfix/1.2.3' }), ['test', 'build', 'deploy-staging'])
  })
}
